beforeExample:
package test;
import org.eclipse.jdt.core.IModuleDescription; // Assume this interface exists with exists(), equals(), and isAutoModule()

class MyClass {
    void checkModule(IModuleDescription projectModule, IModuleDescription currentModuleDescription) {
        if (projectModule != null && projectModule.exists() && !projectModule.equals(currentModuleDescription) && !"JAVA_BASE".equals(projectModule.getElementName())) {
            System.out.println("Module condition met (old)");
        }
    }
}

afterExample:
package test;
import org.eclipse.jdt.core.IModuleDescription;

class MyClass {
    void checkModule(IModuleDescription projectModule, IModuleDescription currentModuleDescription) {
        if (projectModule != null && ((projectModule.exists() && !projectModule.equals(currentModuleDescription)) || projectModule.isAutoModule()) && !"JAVA_BASE".equals(projectModule.getElementName())) {
            System.out.println("Module condition met (new)");
        }
    }
}

